-- =====================================================================
-- SSOL import 2/2 — knowledge_chunks (import 1/2를 먼저 실행하세요)
-- 자동 생성 파일입니다 (scripts/build_import_sql.pl). 직접 수정하지 마세요.
-- Supabase SQL Editor에 전체를 붙여넣고 Run 하세요. 여러 번 실행해도 안전합니다(upsert).
-- 전체가 하나의 트랜잭션이라 오류가 나면 아무것도 저장되지 않습니다.
-- =====================================================================

begin;

-- ---- knowledge_chunks (82행) ----
on conflict (chunk_id) do update set
  article_id = excluded.article_id,
  chunk_order = excluded.chunk_order,
  chunk_title = excluded.chunk_title,
  chunk_text = excluded.chunk_text,
  domain_tags = excluded.domain_tags,
  issue_tags = excluded.issue_tags,
  wellness_theme = excluded.wellness_theme,
  persona_tags = excluded.persona_tags,
  use_when = excluded.use_when,
  follow_up_prompt = excluded.follow_up_prompt,
  evidence_level = excluded.evidence_level,
  ai_attribution_rule = excluded.ai_attribution_rule,
  do_not = excluded.do_not,
  do_not_apply_when = excluded.do_not_apply_when,
  priority = excluded.priority,
  embedding = case when public.knowledge_chunks.chunk_text is distinct from excluded.chunk_text then null else public.knowledge_chunks.embedding end,
  updated_at = now();

commit;
