insert into public.knowledge_chunks (chunk_id, article_id, chunk_order, chunk_title, chunk_text, domain_tags, issue_tags, wellness_theme, persona_tags, use_when, follow_up_prompt, evidence_level, ai_attribution_rule, do_not, do_not_apply_when, priority, is_active)
values
  ('HAP001-A', 'SSOL-HAP-001', 1, '불행과 행복의 구분', '불편함과 고통을 피하는 것은 자연스러운 경향이지만, 그것만으로 삶의 충만함이 보장되지는 않는다. 안정과 행복은 서로 다른 경험일 수 있다.', array['Self','Life Direction']::text[], array['공허함','행복감 저하']::text[], array['행복','의미·방향']::text[], array['요거트파르페','에스프레소브라우니']::text[], '별 문제 없는데 공허함/행복하지 않음', '요즘 삶에서 ''기대되는 것''이 있나요?', 'Medium', '''쏠에서는 ~라는 관점을 제안해요''', '공허함의 원인을 단정하지 않음', null, 'High', true),
  ('HAP001-B', 'SSOL-HAP-001', 2, '안전지대와 새로운 경험', '불행을 피하는 데만 집중하면 새로운 도전이나 시도를 줄이게 되고, 그 결과 삶이 단조롭거나 공허하게 느껴질 수 있다.', array['Self','Life Direction']::text[], array['안전지대','무기력']::text[], array['행복','회피']::text[], array['요거트파르페','카라멜푸딩']::text[], '편하지만 재미없음/변화 두려움', '지금의 편안함을 유지하면서 아주 작은 새 시도는 무엇일까요?', 'Medium', '쏠 관점으로 제시', '''안전지대를 벗어나야 행복'' 단정 금지', null, 'Medium', true),
  ('HAP001-C', 'SSOL-HAP-001', 3, '행복의 3층', '행복은 감각적 즐거움, 몰입과 성취에서 오는 만족감, 더 큰 가치와 연결되는 의미감처럼 서로 다른 층위로 구분해 성찰할 수 있다.', array['Self','Life Direction']::text[], array['행복','만족','의미']::text[], array['행복','의미·방향']::text[], array['요거트파르페','피스타치오크루아상']::text[], '행복이 뭔지 모르겠음/공허함', '즐거움, 성취감, 의미감 중 최근 가장 부족한 것은 무엇인가요?', 'Medium', '설명 프레임으로 사용', '3층을 유일한 진짜 행복으로 절대화 금지', null, 'High', true),
  ('HAP001-D', 'SSOL-HAP-001', 4, '정크푸드 행복', '즉각적인 자극과 쾌감만 반복적으로 추구하면 일시적 즐거움은 얻지만 더 깊은 만족이나 의미가 충분히 채워지지 않을 수 있다.', array['Self']::text[], array['SNS','자극','공허함']::text[], array['행복']::text[], array['요거트파르페','에스프레소브라우니']::text[], 'SNS/쇼핑/자극은 많은데 공허함', '최근 즐거웠지만 금방 사라진 경험과 오래 남은 경험은 각각 무엇인가요?', 'Medium', '완곡한 가능성 표현', 'SNS를 줄이면 행복해진다는 처방 금지', null, 'Medium', true),
  ('HAP001-E', 'SSOL-HAP-001', 5, '의미와 연결감', '삶의 의미는 자신이 하는 일이 더 큰 가치나 타인과 연결된다고 느낄 때 강해질 수 있다.', array['Life Direction','Career']::text[], array['의미','소명','창작']::text[], array['의미·방향']::text[], array['피스타치오크루아상','카스텔라']::text[], '일은 하는데 의미가 없음', '지금 하는 일에서 누구 또는 무엇과 연결되어 있다고 느끼나요?', 'Medium', '가능성/성찰 프레임', '무의미의 원인을 단정하지 않음', null, 'Medium', true),
  ('ROM001-A', 'SSOL-ROM-001', 1, '다툼 자체와 관계 실패는 다름', '연인 사이에서 다툼이 반복된다는 사실만으로 관계가 잘못됐다고 판단하기는 어렵다. 중요한 것은 갈등의 존재뿐 아니라 그 갈등을 어떻게 다루고 회복하는지다.', array['Romance','Relationship']::text[], array['잦은 다툼','관계 불안']::text[], array['관계·소속','직면']::text[], array['딸기마카롱','슈크림빵']::text[], '맨날 싸움/헤어질지 고민', '보통 다툰 뒤에는 어떻게 마무리되나요?', 'Medium-High', '근거가 있는 일반 관계원칙으로 사용 가능', '싸움 빈도만으로 관계 좋고 나쁨 판정 금지', array['신체적 폭력','성적 강요','협박','스토킹','지속적 모욕/위협']::text[], 'High', true),
  ('ROM001-B', 'SSOL-ROM-001', 2, '지속적 갈등', '장기 관계에는 완전히 사라지기 어려운 반복적 갈등이 존재할 수 있으며, 성격·가치관·생활방식 차이에서 비롯될 수 있다.', array['Romance']::text[], array['반복 갈등','차이']::text[], array['관계·소속']::text[], array['딸기마카롱','슈크림빵']::text[], '같은 주제로 반복 싸움', '이 갈등은 해결 가능한 문제인가요, 아니면 반복되는 성향 차이에 가까운가요?', 'High', '검증된 근거와 함께 사용', '특정 수치 사용 시 출처 검증 필요', array['학대/안전 위협 관계']::text[], 'High', true),
  ('ROM001-C', 'SSOL-ROM-001', 3, '해결보다 관리', '반복되는 갈등은 완전한 해결보다 서로의 차이를 이해하고 대화를 지속할 수 있는 방식으로 관리하는 것이 중요할 수 있다.', array['Romance']::text[], array['갈등 관리','소통']::text[], array['관계·소속','직면']::text[], array['딸기마카롱','슈크림빵']::text[], '반복 갈등 해결 안 됨', '싸울 때 서로에게 어떤 말을 하고, 이후 다시 연결되는 방식은 어떤가요?', 'High', '일반 관계원칙', '무조건 참으라고 하지 않음', array['학대/위협']::text[], 'High', true),
  ('ROM001-D', 'SSOL-ROM-001', 4, '감정 표현과 공동 결정', '중요한 관계 결정을 내리기 전에 자신의 서운함, 두려움, 기대를 충분히 전달하고 상대의 반응을 확인하는 과정이 필요할 수 있다.', array['Romance']::text[], array['결혼','이별','감정 표현']::text[], array['관계·소속','의미·방향']::text[], array['딸기마카롱','티라미수']::text[], '결혼/이별 큰 결정', '상대에게 아직 충분히 말하지 못한 감정이나 기대가 있나요?', 'Medium', '쏠 관계 프레임', '이별/결혼을 대신 결정하지 않음', array['안전 우려 시 공동 대화 우선 권고 금지']::text[], 'High', true),
  ('ROM001-E', 'SSOL-ROM-001', 5, '관계의 책임', '관계 갈등을 다룰 때 상대의 행동만 평가하기보다 내가 무엇을 느끼고 원하는지, 내가 조정할 수 있는 부분이 무엇인지 함께 살펴볼 필요가 있다.', array['Romance']::text[], array['책임','조율']::text[], array['관계·소속','직면']::text[], array['딸기마카롱','슈크림빵']::text[], '상대 탓만 반복/변화 요구', '상대가 바뀌어야 할 부분 말고 내가 할 수 있는 부분은 무엇일까요?', 'Medium', '성찰 관점', '피해 상황에서 피해자 책임 암시 금지', array['폭력','강요','권력불균형']::text[], 'High', true),
  ('SELF002-A', 'SSOL-SELF-002', 1, '끈기는 도구', '끈기와 노력은 항상 유지해야 하는 성격적 미덕이라기보다, 필요할 때 선택적으로 사용하는 도구로 볼 수 있다.', array['Self','Career']::text[], array['과도한 노력','집착']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','에스프레소브라우니']::text[], '쉬면 불안/더 해야 함', '지금 더 노력하고 싶은 건 원하는 목표 때문인가요, 멈추는 게 불안해서인가요?', 'Medium', '쏠 철학으로 attribution', '문화 일반화 금지', null, 'Medium', true),
  ('SELF002-B', 'SSOL-SELF-002', 2, '불안 기반 노력', '지속적인 노력은 목표와 이유가 분명할 때 자원으로 작동하지만, 불안이나 죄책감을 피하기 위한 노력은 에너지만 소모할 수 있다.', array['Self','Career']::text[], array['휴식 죄책감','과로']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','티라미수']::text[], '쉬면 죄책감', '아무도 평가하지 않는다면 지금만큼 열심히 하고 싶을까요?', 'Medium', '쏠 프레임', '사용자의 노력 동기를 단정하지 않음', null, 'High', true),
  ('SELF002-C', 'SSOL-SELF-002', 3, '에너지 배분', '모든 상황에서 최대한 애쓰려 하면 정작 중요한 순간에 사용할 심리적·신체적 에너지가 부족해질 수 있다.', array['Self','Career']::text[], array['에너지 관리','소진']::text[], array['자기가치·인정']::text[], array['에스프레소브라우니','밀푀유']::text[], '항상 바쁨/소진', '지금 쓰는 에너지는 정말 중요한 곳에 쓰이고 있나요?', 'Medium', '일반적 자기조절 관점', '의학적 소진 진단 금지', null, 'Medium', true),
  ('SELF003-A', 'SSOL-SELF-003', 1, '최선과 최대치의 차이', '최선을 다하는 것은 언제나 가능한 최대치까지 노력하는 것과 같지 않다. 최선은 현재 자신의 상태와 상황을 고려해 적절한 수준의 노력을 선택하는 과정으로 볼 수 있다.', array['Self','Career']::text[], array['최선 압박','완벽주의']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','에스프레소브라우니']::text[], '더 할 수 있었는데 안 했음', '오늘의 나에게 가능한 최선과 머릿속 이상적 최선은 얼마나 다른가요?', 'Medium', '쏠 철학', '최선을 대신 판정 금지', null, 'High', true),
  ('SELF003-B', 'SSOL-SELF-003', 2, '할 수 있는 것과 없는 것', '자신의 능력과 현재 자원을 정확히 파악하는 것은 노력의 일부다. 감당하기 어려운 일을 무조건 밀어붙이지 않는 것도 자기조절의 한 형태가 될 수 있다.', array['Self']::text[], array['한계','에너지']::text[], array['통제·미래','자기가치·인정']::text[], array['밀푀유','티라미수']::text[], '무리해야만 목표 가능', '하지 못하는 것, 하기 싫은 것, 지금은 하지 않는 게 좋은 것을 구분하면 무엇인가요?', 'Medium', '성찰 프레임', '힘들면 무조건 하지 말라는 조언 금지', null, 'High', true),
  ('SELF003-C', 'SSOL-SELF-003', 3, '충분함의 감각', '''이 정도면 충분하다''는 기준은 고정된 숫자라기보다 경험을 통해 자신의 능력과 한계를 알아가며 형성될 수 있다.', array['Self']::text[], array['완료 기준','충분함']::text[], array['자기가치·인정']::text[], array['밀푀유','티라미수']::text[], '성과 기준 불명확', '오늘의 완료 기준을 한 문장으로 정하면 어디까지인가요?', 'Medium', '쏠 프레임', '충분함을 AI가 대신 결정 금지', null, 'High', true),
  ('SELF004-A', 'SSOL-SELF-004', 1, '성공의 복합성', '성공은 개인의 재능과 노력뿐 아니라 환경, 기회, 사회적 조건, 우연 등의 영향을 함께 받을 수 있다.', array['Self','Career']::text[], array['성공','성과','비교']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','티라미수']::text[], '타인 성공과 비교/자기비난', '이번 결과에서 내가 통제할 수 있었던 것과 없었던 것을 나누면 무엇인가요?', 'Needs verification', '''쏠의 글에서는 ~라는 관점을 제시해요''', '성공은 운이라고 단정 금지', null, 'Medium', false),
  ('SELF004-B', 'SSOL-SELF-004', 2, '비교의 함정', '다른 사람의 성공 결과만 보고 자신의 능력이나 가치를 평가하면 서로 다른 환경과 기회의 차이를 놓칠 수 있다.', array['Self','Career']::text[], array['비교','자기비난']::text[], array['자기가치·인정']::text[], array['밀푀유','에스프레소브라우니']::text[], '친구/동료와 비교', '지금 비교하는 사람과 당신의 출발 조건은 얼마나 비슷했나요?', 'Medium', '일반 성찰', '타인의 성공 폄하 금지', null, 'High', true),
  ('SELF004-C', 'SSOL-SELF-004', 3, '통제 범위', '중요한 결과를 평가할 때 자신이 통제할 수 있었던 요소와 통제하기 어려웠던 요소를 구분하면 과도한 자기비난을 줄이고 다음 행동을 더 현실적으로 설계할 수 있다.', array['Self','Career']::text[], array['통제','실패']::text[], array['통제·미래']::text[], array['티라미수','밀푀유']::text[], '실패 후 자기비난', '이번 경험에서 다음번에 바꿀 수 있는 한 가지는 무엇인가요?', 'Medium', '성찰 프레임', '결과 책임을 전부 외부로 돌리지 않음', null, 'High', true),
  ('SELF005-A', 'SSOL-SELF-005', 1, '자기신뢰와 고집의 차이', '자신의 방향과 선택을 믿는 것과 외부 의견을 무시하는 것은 다르다. 피드백은 참고하되 타인의 평가가 곧 자기부정으로 이어지지 않도록 구분할 필요가 있다.', array['Self','Study','Career']::text[], array['자기의심','외부평가']::text[], array['자기가치·인정']::text[], array['밀푀유','티라미수']::text[], '남의 말에 흔들림', '다른 사람의 의견 중 참고할 부분과 나를 위축시키는 부분은 각각 무엇인가요?', 'Medium', '쏠 철학', '남의 말 무시 권고 금지', null, 'Medium', true),
  ('SELF005-B', 'SSOL-SELF-005', 2, '흔들림과 회복', '심리적 안정은 한 번도 흔들리지 않는 상태라기보다 흔들린 뒤 다시 중심을 찾는 능력으로 볼 수 있다.', array['Self','Study']::text[], array['시험 불안','회복']::text[], array['통제·미래','직면']::text[], array['티라미수','카라멜푸딩']::text[], '시험 직전 불안/계획 무너짐', '다시 시작하기 위한 가장 작은 행동은 무엇일까요?', 'Medium', '쏠 프레임', '불안을 정상화하되 심각한 기능저하 무시 금지', null, 'High', true),
  ('SELF005-C', 'SSOL-SELF-005', 3, '유연한 조절', '모든 상황을 통제할 수는 없지만, 변화하는 상황에 맞춰 속도와 방법을 조정할 수는 있다.', array['Self','Study','Life Direction']::text[], array['유연함','계획 변경']::text[], array['통제·미래']::text[], array['티라미수','카라멜푸딩']::text[], '계획 틀어짐', '지금은 더 밀어붙여야 하는 때인가요, 아니면 속도를 조절해야 하는 때인가요?', 'Medium', '쏠 철학', '무조건 유연해야 한다는 압박 금지', null, 'Medium', true),
  ('SELF006-A', 'SSOL-SELF-006', 1, '자기조절 실패와 자기비난', '계획한 행동을 지속하지 못했다고 해서 곧바로 의지박약이나 게으름으로 해석할 필요는 없다. 자기조절은 현재의 피로, 스트레스, 동기, 환경의 영향을 받을 수 있다.', array['Self','Daily Habits']::text[], array['의지박약','미루기','운동 실패']::text[], array['통제·미래','자기가치·인정']::text[], array['티라미수','밀푀유','카라멜푸딩']::text[], '운동/공부/식습관 실패 후 자책', '이 행동을 실패했던 날에는 이미 어떤 스트레스나 에너지를 많이 쓰고 있었나요?', 'High', '일반 심리학적 관점', '''의지력이 고갈됐다'' 단정 금지', null, 'High', true),
  ('SELF006-B', 'SSOL-SELF-006', 2, '상황 의존성', '같은 사람도 하루 동안 요구되는 일의 양, 피로, 스트레스, 환경에 따라 이후의 자기조절이 더 어렵거나 쉬워질 수 있다.', array['Self','Daily Habits']::text[], array['피로','스트레스','자기조절']::text[], array['통제·미래']::text[], array['티라미수','카라멜푸딩']::text[], '퇴근 후 운동 못함/야식', '운동을 못 가는 날에는 보통 회사에서 어떤 하루를 보내나요?', 'High', '일반 심리학적 관점', '상황만 탓하게 하지 않음', null, 'High', true),
  ('SELF006-C', 'SSOL-SELF-006', 3, '환경 설계', '행동을 지속하기 어려울 때는 의지만 강화하려 하기보다 방해 요소를 줄이고 행동을 쉽게 시작할 수 있도록 환경을 조정하는 것도 중요하다.', array['Self','Daily Habits']::text[], array['환경설계','습관']::text[], array['통제·미래']::text[], array['티라미수','카라멜푸딩']::text[], '습관 실패 반복', '집에 갔다가 다시 나오는 것과 바로 시작하는 것 중 어느 쪽이 덜 어려울까요?', 'High', '일반 행동과학 관점', '의지만으로 해결 가능하다고 말하지 않음', null, 'High', true),
  ('SELF006-D', 'SSOL-SELF-006', 4, '작은 행동', '큰 변화를 한 번에 시도하기보다 작은 행동을 반복하며 실행 경험을 쌓는 방식이 도움이 될 수 있다.', array['Self','Daily Habits']::text[], array['작은 행동','습관']::text[], array['직면','통제·미래']::text[], array['카라멜푸딩','티라미수']::text[], '목표가 너무 큼', '이번 주 가장 작게 줄이면 어떤 행동까지는 할 수 있을까요?', 'Medium', '가능성 표현', '작은 행동이 항상 성공 보장한다고 말하지 않음', null, 'Medium', true),
  ('ROM002-A', 'SSOL-ROM-002', 1, '사랑의 학습 가능성', '사랑을 주고받는 방식은 타고난 성격만으로 결정되지 않으며, 관계 경험과 반복적인 연습을 통해 익숙해질 수 있다.', array['Romance','Relationship']::text[], array['연애 서툼','친밀감']::text[], array['관계·소속']::text[], array['슈크림빵','딸기마카롱']::text[], '연애에 소질 없다고 느낌', '연애에서 서툴다고 느끼는 부분이 표현, 의지하기, 갈등 대화, 친밀감 중 어디에 가까운가요?', 'Medium', '쏠 관점', '누구나 연습하면 잘할 수 있다고 보장 금지', null, 'High', true),
  ('ROM002-B', 'SSOL-ROM-002', 2, '관계의 서툼과 경험', '관계에 익숙하지 않다는 사실이 사랑할 능력이 없다는 뜻은 아니다. 일부 관계 기술은 반복적인 경험을 통해 더 자연스러워질 수 있다.', array['Romance','Relationship']::text[], array['관계 경험 부족','자기의심']::text[], array['관계·소속','자기가치·인정']::text[], array['슈크림빵']::text[], '연애 경험 부족/모태솔로 자기비난', '나는 연애를 못한다는 말 대신, 어떤 행동이 가장 어려운지 나눠보면 무엇인가요?', 'Medium', '쏠 관점', '과거 양육을 원인으로 단정 금지', null, 'High', true),
  ('ROM002-C', 'SSOL-ROM-002', 3, '작은 관계 기술', '친밀감은 거창한 감정만으로 유지되는 것이 아니라 표현하기, 듣기, 부탁하기, 사과하기, 다시 연결하기 같은 구체적인 행동을 통해 형성될 수 있다.', array['Romance','Relationship']::text[], array['감정표현','도움요청','갈등회복']::text[], array['관계·소속','직면']::text[], array['슈크림빵','딸기마카롱']::text[], '표현 어려움/도움받기 어려움', '표현하기, 기대기, 서운함 말하기, 갈등 후 다시 대화하기 중 무엇이 가장 어렵나요?', 'Medium', '쏠 프레임', '행동 기술만으로 관계 전부 설명 금지', null, 'High', true),
  ('ADHD001-A', 'SSOL-ADHD-001', 1, 'ADHD와 동기·보상 처리', 'ADHD에서는 보상 처리와 동기 관련 어려움이 나타날 수 있으며, 흥미도·즉각적 보상·과제 특성에 따라 집중과 실행의 난이도가 달라질 수 있다.', array['Self','Career','Creative Work']::text[], array['ADHD','동기','보상','실행']::text[], array['의미·방향','통제·미래']::text[], array['피스타치오크루아상','에스프레소브라우니','카라멜푸딩']::text[], 'ADHD가 있고 반복·단조로운 작업을 시작하기 어렵다고 말함', '어떤 종류의 작업에서는 비교적 쉽게 몰입하고, 어떤 작업에서 특히 시작이 어려운가요?', 'High', '일반적 ADHD 특성으로 사용하되 개인차를 강조', '도파민이 ''충분히 분비되지 않는다''처럼 단순한 신경화학 설명 금지', null, 'High', true),
  ('ADHD001-B', 'SSOL-ADHD-001', 2, '의미와 과제 참여', '개인적으로 중요하거나 흥미로운 과제는 일부 ADHD 성향의 사람에게 참여와 지속을 쉽게 만들 수 있지만, 의미가 있다고 해서 실행 문제가 자동으로 해결되는 것은 아니다.', array['Career','Creative Work']::text[], array['ADHD','의미','과제몰입']::text[], array['의미·방향']::text[], array['피스타치오크루아상','에스프레소브라우니']::text[], '창작은 좋아하지만 실행이 들쭉날쭉함', '지금 하려는 작업에서 당신에게 실제로 의미 있는 부분과 단순히 해야 해서 하는 부분을 나누면 각각 무엇인가요?', 'Medium', '쏠의 동기 탐색 프레임으로만 사용', '''의미 있는 일''이면 초집중이 생긴다고 보장 금지', null, 'Medium', true),
  ('ADHD001-C', 'SSOL-ADHD-001', 3, '치료는 개인별 조합', '성인 ADHD 치료에는 약물치료, 심리치료·행동적 개입, 환경 조정 등이 포함될 수 있으며, 개인의 증상과 생활 기능, 선호에 따라 치료 계획이 달라질 수 있다.', array['Self','Clinical']::text[], array['ADHD','치료','약물','심리치료']::text[], array['통제·미래']::text[], null, 'ADHD 치료를 무엇으로 해야 하는지 질문', '치료 선택은 현재 어떤 어려움이 가장 크고, 이미 어떤 평가나 치료를 받아봤는지에 따라 달라질 수 있어요. 의료전문가와 상의해본 적이 있나요?', 'High', '의료 가이드라인에 부합하는 중립적 설명만 사용', '심리상담이 약물보다 우선/황금률이라고 단정 금지 | 약물치료를 단기적 보조로 축소 금지', array['진단 전 사용자가 ADHD라고 단정하는 경우','약물 변경·중단 요청']::text[], 'High', true),
  ('ADHD001-D', 'SSOL-ADHD-001', 4, '창작 환경 설계', 'ADHD 관련 실행 어려움을 다룰 때는 의지만 강조하기보다 과제의 크기, 시작 장벽, 외부 구조, 시간대, 방해 자극 등 실행 환경을 함께 조정하는 것이 도움이 될 수 있다.', array['Career','Creative Work','Daily Habits']::text[], array['ADHD','실행','환경설계','창작']::text[], array['통제·미래','직면']::text[], array['티라미수','카라멜푸딩','에스프레소브라우니']::text[], '아이디어는 많지만 실제 작업 시작이 어려움', '작업을 시작하기 가장 어렵게 만드는 요소가 과제 크기, 장소, 시간대, 방해 자극 중 무엇에 가까운가요?', 'High', '실행지원 관점', '의지 부족으로 설명 금지', null, 'High', true),
  ('ADHD001-E', 'SSOL-ADHD-001', 5, '강점과 어려움을 함께 보기', 'ADHD와 관련된 개인적 특성에서 창의성이나 강점을 느끼는 사람이 있을 수 있지만, ADHD 자체를 보편적인 ''재능''으로 규정하거나 기능상의 어려움을 축소해서는 안 된다.', array['Self','Creative Work']::text[], array['ADHD','강점','정체성']::text[], array['자기가치·인정','의미·방향']::text[], array['피스타치오크루아상']::text[], 'ADHD를 장점으로만 보거나 결함으로만 봄', 'ADHD와 관련해 스스로 강점이라고 느끼는 부분과 실제로 도움이 필요한 부분은 각각 무엇인가요?', 'Medium', '개인의 경험으로만 다룸', '''ADHD는 저주가 아니라 재능''이라고 일반화 금지', null, 'High', true),
  ('PANIC001-A', 'SSOL-PANIC-001', 1, '타인의 시선과 자기 가치', '대중의 평가를 많이 받는 환경에서는 자신의 가치가 외부 반응에 과도하게 좌우되는 느낌을 경험할 수 있으며, 이는 불안과 자기정체성의 흔들림으로 이어질 수 있다.', array['Self','Public-facing Work','Creative Work']::text[], array['평가불안','대중의 시선','자기정체성']::text[], array['자기가치·인정','관계·소속']::text[], array['밀푀유','머랭쿠키']::text[], '타인의 평가·댓글·성과 반응에 지나치게 흔들린다고 말할 때', '최근 가장 크게 흔들리게 만든 타인의 반응은 무엇이었고, 그 반응이 스스로에 대한 평가와 어떻게 연결됐나요?', 'Medium', '쏠의 해석적 관점으로만 제시', '타인의 평가가 공황장애의 직접 원인이라고 단정 금지', null, 'High', true),
  ('PANIC001-B', 'SSOL-PANIC-001', 2, '대중이 만든 이미지와 실제 자기', '공적인 역할이나 이미지가 강한 사람은 타인이 기대하는 모습과 실제 자신의 모습 사이에 간극을 느낄 수 있다. 이 간극이 커질수록 피로감이나 불안을 경험할 수 있다.', array['Self','Public-facing Work']::text[], array['페르소나','자기정체성','평가불안']::text[], array['자기가치·인정','의미·방향']::text[], array['밀푀유','머랭쿠키','티라미수']::text[], '직업적 이미지와 실제 자기 사이의 괴리감을 말할 때', '사람들이 기대하는 모습과 실제 당신의 모습 사이에서 가장 큰 차이는 무엇인가요?', 'Medium', '성찰 프레임으로 사용', '공적 인물이면 반드시 이런 갈등을 겪는다고 일반화 금지', null, 'Medium', true),
  ('PANIC001-C', 'SSOL-PANIC-001', 3, '공황과 신체감각', '공황 발작에서는 심박 증가, 호흡 변화, 어지러움 같은 신체감각이 강한 공포와 함께 나타날 수 있고, 이러한 감각을 위험 신호로 해석하면서 공포가 증폭되는 악순환이 생길 수 있다.', array['Clinical','Self']::text[], array['공황','신체감각','불안','공포']::text[], array['통제·미래']::text[], null, '갑작스러운 심박 증가·숨가쁨·죽을 것 같은 공포를 호소할 때', '이런 신체감각이 반복되거나 일상에 영향을 주고 있나요? 그렇다면 전문적인 평가를 받아보는 것이 도움이 될 수 있어요.', 'High', '임상적으로 알려진 공황 메커니즘을 중립적으로 설명', '사용자의 증상을 공황장애로 진단하지 않음 | 원인을 심리적 갈등 하나로 단정하지 않음', array['흉통·호흡곤란 등 급성 의학적 위험 가능성이 있을 때']::text[], 'High', true),
  ('PANIC001-D', 'SSOL-PANIC-001', 4, '투사는 해석적 프레임', '사람은 때때로 자신의 욕구, 기대, 불편한 감정을 다른 사람에게 투영해 해석할 수 있다는 심리학적 관점이 있다. 다만 특정 집단의 비난이나 찬사를 모두 투사로 설명할 수는 없다.', array['Human Relationships','Public-facing Work']::text[], array['투사','대중반응','비난','이상화']::text[], array['관계·소속','자기가치·인정']::text[], null, '타인의 과도한 이상화·비난을 어떻게 받아들여야 할지 고민할 때', '그 반응 중 실제로 참고할 부분과, 상대의 기대나 감정이 더 많이 반영됐을 수 있는 부분을 나누면 어떻게 보이나요?', 'Medium-Low', 'SSOL 해석 프레임으로 명시', '대중의 모든 반응을 투사로 규정 금지', null, 'Medium', true),
  ('PANIC001-E', 'SSOL-PANIC-001', 5, '외부 평가와 자기 경계', '타인의 평가를 완전히 통제할 수는 없지만, 어떤 평가를 내 가치 판단의 기준으로 받아들일지 경계를 세우는 연습은 도움이 될 수 있다.', array['Self','Public-facing Work']::text[], array['경계','평가불안','자기기준']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','머랭쿠키','티라미수']::text[], '댓글·성과·대중 반응에 과도하게 흔들릴 때', '지금 받고 있는 평가 중 사실 확인에 도움이 되는 피드백과, 당신의 가치 전체를 규정할 필요는 없는 반응을 나누면 무엇인가요?', 'Medium', '쏠의 자기기준 프레임으로 사용', '단순히 타인의 말을 무시하라고 하지 않음', null, 'High', true),
  ('HSP001-A', 'SSOL-HSP-001', 1, '민감성은 한 가지 모습만 있는 것이 아님', '쏠의 이 글은 예민함을 하나의 단일한 모습으로 보지 않고, 쉽게 압도되는 경향, 감각 자극에 대한 민감성, 심미적 감수성처럼 서로 다른 측면으로 나누어 이해하는 관점을 제시한다.', array['Self','Creative Work']::text[], array['HSP','SPS','예민함','민감성','EOE','LST','AES']::text[], array['자기가치·인정','의미·방향']::text[], array['피스타치오크루아상','머랭쿠키']::text[], 'HSP가 무엇인지 묻거나, 평소 무던한데 특정 자극·예술에는 매우 민감하다고 말할 때', '어떤 상황에서 쉽게 압도되고, 어떤 감각 자극에 민감하며, 어떤 장면이나 표현에는 유독 깊게 반응하나요?', 'Medium', '''쏠의 관련 콘텐츠에서는 민감성을 여러 측면으로 나눠볼 수 있다고 제안해요''처럼 사용', 'HSP를 질환·진단으로 표현 금지 | 세 차원이 사용자의 성격을 완전히 설명한다고 단정 금지', null, 'High', true),
  ('HSP001-B', 'SSOL-HSP-001', 2, 'EOE: 쉽게 압도되는 경험', 'EOE(Ease of Excitation)는 여러 요구나 정서적·환경적 자극이 겹칠 때 쉽게 압도되는 경험을 살펴보는 데 사용할 수 있는 하나의 관점이다.', array['Self','Daily Habits']::text[], array['HSP','EOE','과부하','압도']::text[], array['통제·미래','자기가치·인정']::text[], array['티라미수','머랭쿠키']::text[], '해야 할 일이 많거나 여러 자극이 겹치면 쉽게 지친다고 말할 때', '힘들어지는 건 자극 자체가 강할 때인가요, 아니면 여러 가지가 동시에 겹칠 때인가요?', 'Medium', '특성 탐색용으로 사용', 'EOE가 높다고 진단하거나 병리화 금지', null, 'Medium', true),
  ('HSP001-C', 'SSOL-HSP-001', 3, 'LST: 감각 자극에 대한 민감성', 'LST(Low Sensory Threshold)는 소리, 빛, 질감 등 감각 자극을 불편하거나 강하게 경험하는 정도를 살펴보는 관점으로 사용할 수 있다.', array['Self','Daily Habits','Creative Work']::text[], array['HSP','LST','소음','빛','질감','감각민감']::text[], array['통제·미래']::text[], array['머랭쿠키','티라미수']::text[], '소음·빛·공간 자극 때문에 집중이 어렵다고 말할 때', '집중을 가장 많이 방해하는 감각 자극은 소리, 빛, 사람의 움직임, 촉감 중 무엇에 가까운가요?', 'Medium', '환경 탐색용으로 사용', '감각 민감성을 HSP 하나로만 설명 금지', null, 'Medium', true),
  ('HSP001-D', 'SSOL-HSP-001', 4, 'AES: 심미적 민감성과 창작', 'AES(Aesthetic Sensitivity)는 예술, 자연, 미묘한 표현이나 아름다움에 깊이 반응하는 경향을 살펴보는 관점이다. 쏠의 글에서는 이러한 감수성이 일부 창작자에게 영감과 표현의 자원이 될 수 있다고 제안한다.', array['Creative Work','Self']::text[], array['HSP','AES','심미적민감성','감수성','창작','영감']::text[], array['의미·방향','자기가치·인정']::text[], array['피스타치오크루아상']::text[], '평소 둔감해 보이지만 예술·문장·음악·자연에는 깊게 반응한다고 말할 때', '남들은 그냥 지나치는데 당신은 유독 오래 기억하거나 깊게 반응하는 장면은 어떤 종류인가요?', 'Medium', '창작 강점에 대한 SSOL 관점으로 attribution', 'AES가 높으면 창의적이라는 인과 단정 금지 | 민감성을 무조건 재능으로 미화 금지', null, 'High', true),
  ('HSP001-E', 'SSOL-HSP-001', 5, '민감성에 맞는 환경 설계', '자신이 어떤 자극에 쉽게 지치고 어떤 자극에서 영감을 얻는지 구분하면, 불필요한 소진을 줄이면서 집중하기 쉬운 환경을 설계하는 데 참고할 수 있다.', array['Creative Work','Daily Habits','Self']::text[], array['HSP','환경설계','창작환경','에너지관리']::text[], array['통제·미래','의미·방향']::text[], array['티라미수','피스타치오크루아상','머랭쿠키']::text[], '예민함 때문에 지치지만 창작에는 활용하고 싶다고 말할 때', '줄이고 싶은 자극 한 가지와, 오히려 더 가까이 두고 싶은 자극 한 가지를 고른다면 무엇인가요?', 'Medium', '자기이해·환경설계 수준에서 사용', '사용자에게 모든 자극을 피하라고 권하지 않음', null, 'High', true),
  ('HSP001-F', 'SSOL-HSP-001', 6, 'HSP 질문에 대한 기본 안내', 'HSP라는 표현은 사용자가 자신의 민감성을 이해하기 위해 찾는 개념으로 다룰 수 있다. 쏠 AI는 이를 의학적 진단이나 고정된 정체성으로 확정하지 않고, 실제 생활에서 어떤 자극과 상황에 어떻게 반응하는지 구체적으로 탐색한다.', array['Self']::text[], array['HSP','Highly Sensitive Person','SPS','자기이해']::text[], array['자기가치·인정','통제·미래']::text[], null, '사용자가 ''저 HSP인가요?'', ''HSP 특징 알려줘''라고 질문할 때', 'HSP라는 이름이 나에게 맞는지보다, 실제로 어떤 상황에서 민감성이 나타나는지부터 함께 살펴볼까요?', 'High', '비진단적 자기이해 프레임으로 사용', 'AI가 HSP 여부를 판정하지 않음 | HSP를 정신질환으로 표현하지 않음', null, 'High', true),
  ('DEP001-A', 'SSOL-DEP-001', 1, '우울감과 우울증을 동일시하지 않기', '일시적인 우울감은 누구나 경험할 수 있지만, 우울한 상태가 지속되거나 수면·식사·집중·일상 기능에 영향을 준다면 단순한 감정으로만 보지 않고 의료전문가의 평가를 고려해야 한다.', array['Self','Mental Health']::text[], array['우울감','우울증','기능저하']::text[], array['자기가치·인정','통제·미래']::text[], null, '우울증인지 묻거나 우울감이 오래 지속된다고 할 때', '최근 몇 주 동안 기분, 수면, 식사, 에너지, 일상활동 중 가장 많이 달라진 것은 무엇인가요?', 'High', '의학적 진단을 대신하지 않는 일반 안내', 'AI가 우울증 진단 금지|감정 신호로만 축소 금지', array['자살·자해 위험은 SAFE-013 우선']::text[], 'Critical', true),
  ('DEP001-B', 'SSOL-DEP-001', 2, '의료와 자기이해는 대립하지 않음', '의학적 평가와 치료가 필요한 경우 의료전문가의 도움을 받으면서, 별개로 자신의 감정과 삶의 맥락을 이해하는 웰니스 작업을 병행할 수 있다.', array['Self','Mental Health','Life Direction']::text[], array['정신과','상담','치료','자기이해']::text[], array['의미·방향','행복']::text[], null, '병원과 상담/웰니스 중 하나를 선택해야 한다고 느낄 때', '의학적 평가와 별개로 지금 삶에서 이해하고 싶은 부분은 무엇인가요?', 'High', 'SSOL 서비스 경계 설명에 활용', '의료를 대체하거나 치료 중단을 암시하지 않음', null, 'High', true),
  ('DEP001-C', 'SSOL-DEP-001', 3, '힘든 경험을 자기이해에 활용하기', '치료가 필요한 상태를 성장이라는 말로 덮지 않으면서도, 회복 과정에서 자신이 무엇에 지쳤고 무엇을 중요하게 여기는지 돌아볼 수 있다.', array['Self','Life Direction']::text[], array['우울','자기이해','성장']::text[], array['의미·방향','자기가치·인정']::text[], null, '우울 경험의 의미를 묻는 경우', '지금은 원인을 해석하기보다 회복이 우선인가요, 아니면 삶에서 무엇이 달라졌는지 정리해보고 싶나요?', 'Medium', 'SSOL 철학으로 attribution', '고통을 성장 의무로 만들지 않음', null, 'Medium', true),
  ('DEP001-D', 'SSOL-DEP-001', 4, '창작과 우울을 분리하기', '일부 창작자는 힘든 경험을 표현의 재료로 활용할 수 있지만, 고통이 창작에 필요하거나 우울이 창의성을 높인다고 일반화할 수 없다.', array['Creative Work','Mental Health']::text[], array['우울','창작','고통']::text[], array['의미·방향']::text[], null, '고통이 창작에 필요하다고 느낄 때', '치료나 회복과 별개로, 이 경험을 작품에 담고 싶은 부분은 무엇인가요?', 'High', '안전 우선 후 창작 맥락 보조', '치료 회피를 창작 가치로 정당화 금지', null, 'High', true),
  ('DEP001-E', 'SSOL-DEP-001', 5, '외상 후 성장 강요 금지', '힘든 경험 이후 긍정적 변화가 나타날 수 있지만 모든 사람이 성장해야 하는 것은 아니며, 고통이 자동으로 성장으로 이어지는 것도 아니다.', array['Self','Life Direction']::text[], array['외상후성장','회복']::text[], array['의미·방향']::text[], null, '성장해야 한다는 압박을 느낄 때', '지금 이 경험에서 의미를 찾는 것보다 먼저 필요한 것은 무엇인가요?', 'Medium', '가능성으로만 제시', '성장 강요 금지', null, 'Medium', true),
  ('CRE001-A', 'SSOL-CREATIVE-001', 1, '민감성과 재능은 동일하지 않음', '높은 감수성이나 민감성은 창작에 활용될 수 있는 특성 중 하나일 수 있지만, 그 자체가 예술적 재능이나 성취를 보장하지 않는다.', array['Creative Work','Self']::text[], array['민감성','재능','HSP']::text[], array['의미·방향','자기가치·인정']::text[], array['피스타치오크루아상']::text[], '예민함이 재능인지 묻는 경우', '당신의 민감성이 실제로 아이디어나 표현에 도움이 되는 순간은 언제인가요?', 'High', 'SSOL 관점+일반적 주의', '예민할수록 예술적 재능이 높다고 단정 금지', null, 'High', true),
  ('CRE001-B', 'SSOL-CREATIVE-001', 2, '자기 사용설명서', '자신의 민감성이 어떤 조건에서 도움이 되고 어떤 조건에서 부담이 되는지 파악하면 창작환경과 작업방식을 조정하는 데 도움이 될 수 있다.', array['Creative Work','Self']::text[], array['창작환경','에너지','민감성']::text[], array['통제·미래','의미·방향']::text[], array['피스타치오크루아상','머랭쿠키']::text[], '쉽게 지치지만 창작에 활용하고 싶을 때', '집중이 가장 잘 되는 환경과 가장 빨리 지치는 환경을 하나씩 떠올려볼 수 있나요?', 'Medium', '환경설계용', '모든 자극 회피 권고 금지', null, 'Medium', true),
  ('CRE001-C', 'SSOL-CREATIVE-001', 3, '감정의 강도보다 조절과 표현', '창작에 유용한 것은 감정의 강도 자체보다 그 감정을 관찰하고 표현 가능한 형태로 바꾸는 과정일 수 있다.', array['Creative Work','Self']::text[], array['감정조절','창작','표현']::text[], array['의미·방향','직면']::text[], array['피스타치오크루아상']::text[], '감정이 많아 작업이 어렵다고 할 때', '지금 감정 중 바로 표현할 수 있는 것과 먼저 정리할 필요가 있는 것은 무엇인가요?', 'Medium', 'SSOL 관점으로 제시', '고통이 강할수록 좋은 작품이라는 일반화 금지', null, 'Medium', true),
  ('CRE001-D', 'SSOL-CREATIVE-001', 4, '감수성과 표현기술 분리', '깊이 느끼는 것과 그것을 좋은 작품으로 표현하는 것은 같은 능력이 아니며, 표현에는 기술·연습·구조화가 필요할 수 있다.', array['Creative Work']::text[], array['감수성','표현력','완성도']::text[], array['의미·방향']::text[], array['피스타치오크루아상']::text[], '느끼는 건 많은데 작품으로 안 나온다고 할 때', '막히는 지점이 아이디어 구조화, 기술, 완성까지 밀고 가기 중 어디에 가까운가요?', 'High', '실용적 창작 프레임', '감수성 부족을 원인으로 단정 금지', null, 'High', true),
  ('CRE002-A', 'SSOL-CREATIVE-002', 1, '과도한 사유와 실행 지연 구분', '생각과 성찰은 중요하지만 행동 전에 모든 것을 이해하거나 확신하려는 욕구가 실행을 미루는 방식으로 작동할 수 있다.', array['Creative Work','Self']::text[], array['과도한 사유','완벽주의','실행지연']::text[], array['자기가치·인정','직면']::text[], array['밀푀유','피스타치오크루아상']::text[], '생각만 하고 시작 못한다고 할 때', '지금 더 생각하면 실제로 좋아질 부분과, 시작을 미루게 되는 부분은 각각 무엇인가요?', 'High', '가능성 탐색으로 사용', '회피 원인을 실패불안으로 단정 금지', null, 'High', true),
  ('CRE002-B', 'SSOL-CREATIVE-002', 2, '의미는 행동 속에서 선명해질 수 있음', '창작의 의미가 행동 전에 완성되어 있어야 하는 것은 아니며, 만들고 선택하고 수정하는 과정에서 무엇이 중요한지 더 분명해질 수 있다.', array['Creative Work','Life Direction']::text[], array['의미','실행','창작']::text[], array['의미·방향','직면']::text[], array['피스타치오크루아상']::text[], '의미를 완전히 정리해야 시작할 수 있다고 할 때', '오늘 만들 수 있는 가장 작은 조각은 무엇인가요?', 'Medium', 'SSOL 철학으로 attribution', '사유가 무의미하다고 폄하 금지', null, 'High', true),
  ('CRE002-C', 'SSOL-CREATIVE-002', 3, '불완전한 결과를 마주하기', '실행을 미루는 데는 완성도, 평가, 준비되지 않았다는 느낌 등 여러 두려움이 섞여 있을 수 있다.', array['Creative Work','Self']::text[], array['평가불안','실패불안','완벽주의']::text[], array['자기가치·인정','직면']::text[], array['밀푀유']::text[], '결과물을 내기 두려울 때', '실제로 시작했을 때 가장 마주치기 싫은 결과는 무엇인가요?', 'Medium', '탐색 질문으로만', '원인을 단정하지 않음', null, 'High', true),
  ('CRE002-D', 'SSOL-CREATIVE-002', 4, '작은 행동이 동기에 앞설 수 있음', '의욕이 생길 때까지 기다리기보다 아주 작고 구체적인 행동을 먼저 시작하면서 동기나 감정이 뒤따르는 경우도 있다.', array['Creative Work','Daily Habits']::text[], array['행동활성화','미루기','동기']::text[], array['직면','통제·미래']::text[], array['카라멜푸딩','피스타치오크루아상']::text[], '일상적 실행 지연', '지금 5분 안에 할 수 있는 가장 작은 행동은 무엇인가요?', 'Medium', '비임상 일상지원에 사용', '우울증 치료처럼 처방 금지', array['중등도 이상 우울','기능저하']::text[], 'Medium', true),
  ('CRE002-E', 'SSOL-CREATIVE-002', 5, '관계적 지지와 외부 구조', '어떤 사람에게는 행동을 시작하는 데 타인의 격려, 구조, 동행, 책임감 같은 관계적 지지가 도움이 될 수 있다.', array['Creative Work','Self','Relationship']::text[], array['외부구조','동행','공동체']::text[], array['관계·소속','직면']::text[], null, '혼자 하면 계속 미룬다고 할 때', '혼자 있을 때보다 누군가에게 중간 결과를 보여줄 때 더 잘 움직이는 편인가요?', 'Medium', '가능성으로 제시', '혼자 못 하는 것을 약함으로 규정 금지', null, 'Medium', true),
  ('MIND001-A', 'SSOL-MIND-001', 1, '마음챙김은 만능 처방이 아님', '마음챙김은 도움이 될 수 있는 방법 중 하나지만 모든 사람에게 동일한 방식으로 맞는 것은 아니다. 불안·자기비판·압도감이 커진다면 방법과 강도를 조정할 필요가 있다.', array['Self','Mental Wellness']::text[], array['마음챙김','명상','불안']::text[], array['통제·미래','자기가치·인정']::text[], null, '명상하면 더 힘들어진다고 할 때', '명상할 때 힘든 건 생각 증가, 자기비판, 몸의 불편감 중 어느 쪽에 가깝나요?', 'High', '일반 웰니스 안내', '명상은 항상 좋다/나쁘다 단정 금지', null, 'High', true),
  ('MIND001-B', 'SSOL-MIND-001', 2, '알아차림과 자기비판 분리', '자신을 관찰하는 능력이 높다고 해서 비판단적 관찰이 자동으로 가능한 것은 아니며, 자기관찰이 자기평가와 결합되면 불편함이 커질 수 있다.', array['Self']::text[], array['자기비판','알아차림']::text[], array['자기가치·인정']::text[], null, '명상 중 스스로를 평가할 때', '지금 일어난 생각을 관찰하는 것과 그 생각을 평가하는 것이 섞여 있지는 않나요?', 'Medium', 'SSOL 관점', '자기비판을 병리로 단정 금지', null, 'Medium', true),
  ('MIND001-C', 'SSOL-MIND-001', 3, '자기자비를 먼저 둘 수 있음', '자기비판이 강한 사람에게는 판단을 없애려 하기보다 불편함을 알아차리면서 스스로에게 친절한 태도를 연습하는 것이 더 접근하기 쉬울 수 있다.', array['Self']::text[], array['자기자비','자기비판']::text[], array['자기가치·인정']::text[], null, '자기비난이 강할 때', '같은 상황의 가까운 사람에게 해줄 말을 나에게도 해본다면 어떤 말이 될까요?', 'Medium', 'SSOL/CFT 관련 관점', '자비가 모든 사람의 선결조건이라고 단정 금지', null, 'Medium', true),
  ('MIND001-D', 'SSOL-MIND-001', 4, '트라우마 관련 신체집중은 신중하게', '과거 트라우마 경험, 해리, 공황 반응이 있는 사람에게 신체감각 집중이 강한 불편감이나 압도감을 유발할 수 있어 신중한 접근과 전문가 도움을 고려할 수 있다.', array['Self','Mental Health']::text[], array['트라우마','해리','공황','바디스캔']::text[], array['통제·미래']::text[], null, '바디스캔 중 강한 반응이 있을 때', '어떤 방식의 명상에서 특히 강한 반응이 나타났나요?', 'High', '임상 경계 우선', 'AI가 트라우마 노출치료 시행 금지', array['공황','해리','트라우마 재경험']::text[], 'Critical', true),
  ('MIND001-E', 'SSOL-MIND-001', 5, '안전감 우선', '몸 내부 감각에 바로 집중하기 어렵다면 현재 환경에서 비교적 안전하고 편안하게 느껴지는 외부 감각이나 지지감을 확인하는 방식이 도움이 될 수 있다.', array['Self','Daily Habits']::text[], array['안전감','그라운딩','외부감각']::text[], array['통제·미래']::text[], null, '가벼운 불안|과도한 내적집중', '지금 주변에서 비교적 편안하거나 안정적으로 느껴지는 감각이 있나요?', 'Medium', '일상적 안정감 탐색', '치료기법으로 처방 금지', array['강한 공황','트라우마 반응']::text[], 'Medium', true),
  ('CRT001-A', 'SSOL-CREATOR-001', 1, '성과지표와 자기 가치 분리', '조회수, 팔로워, 좋아요, 매출 같은 수치는 콘텐츠나 비즈니스 성과를 보여주는 지표일 수 있지만 개인 전체의 가치나 정체성을 측정하는 지표는 아니다.', array['Creative Work','Career','Self']::text[], array['조회수','좋아요','성과지표','자기 가치']::text[], array['자기가치·인정','통제·미래']::text[], array['밀푀유','티라미수']::text[], '숫자에 따라 자기 가치가 흔들릴 때', '지금 보고 있는 숫자는 콘텐츠 성과를 말하나요, 아니면 어느 순간 나의 가치까지 말하는 숫자가 되었나요?', 'High', 'SSOL creator perspective', '숫자 자체가 무의미하다고 말하지 않음', null, 'High', true),
  ('CRT001-B', 'SSOL-CREATOR-001', 2, '공적 페르소나와 실제 자기', '대중이 기대하는 이미지와 실제 자기 사이의 차이가 커지면 정체성 혼란이나 피로감을 느낄 수 있다.', array['Creative Work','Self']::text[], array['페르소나','정체성','대중평가']::text[], array['자기가치·인정','의미·방향']::text[], null, '브랜드 이미지와 실제 자신이 다르다고 할 때', '사람들이 좋아하는 모습과 아무도 보지 않을 때의 당신 사이에서 가장 큰 차이는 무엇인가요?', 'Medium', '가능성으로 제시', '괴리를 질환의 원인으로 단정 금지', null, 'High', true),
  ('CRT001-C', 'SSOL-CREATOR-001', 3, '휴식이 위협처럼 느껴질 수 있음', '성과가 지속적으로 노출되고 비교되는 직업에서는 휴식이 단순한 휴식이 아니라 도태될 수 있다는 불안과 연결될 수 있다.', array['Creative Work','Career']::text[], array['휴식불안','성과압박','번아웃']::text[], array['통제·미래','자기가치·인정']::text[], null, '쉬면 잊힐까 두려울 때', '쉬었을 때 실제로 잃을 수 있는 것과, 잃을 것 같아 두려운 것을 나누면 무엇인가요?', 'Medium', '직업 구조와 개인 반응을 함께 탐색', '휴식만이 해결책이라고 처방 금지', null, 'Medium', true),
  ('CRT001-D', 'SSOL-CREATOR-001', 4, '내면의 기준 다시 세우기', '외부 지표가 중요한 직업일수록 그 지표와 별개로 자신이 중요하게 여기는 가치와 기준을 정리하는 것이 도움이 될 수 있다.', array['Creative Work','Life Direction']::text[], array['내적기준','가치','성과']::text[], array['의미·방향','자기가치·인정']::text[], array['피스타치오크루아상']::text[], '외부반응에 흔들릴 때', '조회수나 반응을 전혀 볼 수 없다고 가정하면 지금도 만들고 싶은 콘텐츠는 무엇인가요?', 'High', 'SSOL 철학', '외부 지표를 무시하라고 하지 않음', null, 'High', true),
  ('CRT002-A', 'SSOL-CREATOR-002', 1, '반복 확인 루프', '조회수·좋아요·구독자 수를 반복적으로 확인하는 행동이 불안을 잠시 낮출 수 있지만, 숫자에 대한 주의가 더 강화될 수도 있다.', array['Creative Work','Daily Habits']::text[], array['강박적 확인','조회수','불안']::text[], array['통제·미래']::text[], null, '분석창을 계속 확인할 때', '숫자를 확인하기 직전과 직후의 감정은 어떻게 달라지나요?', 'Medium', '가능성 탐색', '강박장애 진단 금지', null, 'Medium', true),
  ('CRT002-B', 'SSOL-CREATOR-002', 2, '대중 연결과 친밀감은 다름', '많은 사람에게 노출되어 있다고 해서 실제로 가까운 관계와 정서적 지지가 충분하다는 뜻은 아니다.', array['Creative Work','Relationship']::text[], array['고립','외로움','대중노출']::text[], array['관계·소속']::text[], null, '팔로워는 많지만 외롭다고 할 때', '당신을 크리에이터가 아니라 그냥 한 사람으로 대해주는 사람은 지금 몇 명이나 떠오르나요?', 'Medium', '일상 관계 탐색', '외로움의 원인을 직업으로만 단정 금지', null, 'Medium', true),
  ('CRT002-C', 'SSOL-CREATOR-002', 3, '구조적 위험요인', '크리에이터의 스트레스에는 수입 변동성, 플랫폼 알고리즘, 공개 평가, 온라인 공격, 업무와 사생활 경계의 불분명함 같은 구조적 요인도 영향을 줄 수 있다.', array['Creative Work','Career']::text[], array['플랫폼','재정불안','온라인폭력','번아웃']::text[], array['통제·미래','자기가치·인정']::text[], null, '직업 구조가 힘들다고 할 때', '지금 힘든 부분 중 내가 통제할 수 있는 것과 구조적으로 통제하기 어려운 것은 무엇인가요?', 'Medium', '구조/개인 균형', '산업구조가 단일 원인이라고 단정 금지', null, 'Medium', true),
  ('CRT002-D', 'SSOL-CREATOR-002', 4, '생활리듬과 사회적 지지', '불규칙한 작업과 성과 압박이 강한 직업에서는 수면, 식사, 운동, 오프라인 관계 같은 기본 생활리듬과 사회적 지지가 심리적 안정에 도움이 될 수 있다.', array['Creative Work','Daily Habits','Relationship']::text[], array['수면','식사','운동','사회적지지']::text[], array['행복','관계·소속']::text[], null, '번아웃|생활붕괴', '최근 일주일에서 가장 먼저 무너진 생활리듬은 무엇인가요?', 'Medium', '보호요인으로만', '생활습관이 치료를 대체한다고 암시 금지', null, 'Medium', true),
  ('EMO001-A', 'SSOL-EMOTION-001', 1, '감정의 강도와 충동 행동 분리', '감정을 강하게 경험하는 것과 그 감정에 즉시 행동으로 반응하는 것은 같은 현상이 아니다.', array['Self','Relationship']::text[], array['감정적','충동적','감정조절']::text[], array['자기가치·인정','관계·소속']::text[], array['딸기마카롱','머랭쿠키']::text[], '너무 감정적이라 문제라고 할 때', '감정이 크게 올라오는 것과 그 직후 행동해버리는 것 중 지금 더 힘든 건 어느 쪽인가요?', 'High', '일반 자기이해 프레임', '감정적=충동적 단정 금지', null, 'High', true),
  ('EMO001-B', 'SSOL-EMOTION-001', 2, '자극과 행동 사이의 사이', '충동적으로 반응하기 전에 현재의 감정과 욕구를 확인할 짧은 ''사이''를 만드는 것은 행동 선택지를 늘리는 데 도움이 될 수 있다.', array['Self','Relationship','Daily Habits']::text[], array['충동','반응','감정인식']::text[], array['직면','통제·미래']::text[], null, '화나면 바로 메시지/행동할 때', '지금 행동하기 전에 감정에 이름을 붙인다면 무엇에 가장 가까운가요?', 'High', '웰니스 대화 패턴', '위험한 충동은 안전 규칙 우선', array['자해','자살','심한 공격성','위험행동']::text[], 'High', true),
  ('EMO001-C', 'SSOL-EMOTION-001', 3, '감정은 정보이지 명령이 아님', '감정은 무엇이 중요하게 느껴지는지, 어떤 욕구나 기대가 충족되거나 위협받는지 이해하는 데 도움이 되는 정보가 될 수 있지만 행동의 정답 자체는 아니다.', array['Self','Relationship']::text[], array['감정','욕구','의사결정']::text[], array['의미·방향','관계·소속']::text[], null, '감정을 따라야 할지 이성을 따라야 할지 묻는 경우', '이 감정이 알려주는 중요한 것은 무엇이고, 행동으로 옮기기 전에 확인할 현실 조건은 무엇인가요?', 'High', 'SSOL response philosophy', '감정=진실/정답으로 단정 금지', null, 'High', true),
  ('EMO001-D', 'SSOL-EMOTION-001', 4, '감정에 이름 붙이기', '현재 감정을 더 구체적으로 구분하고 표현하는 과정은 자신의 반응을 이해하고 행동을 선택하는 데 도움이 될 수 있다.', array['Self','Relationship']::text[], array['감정명명','감정표현']::text[], array['자기가치·인정','관계·소속']::text[], null, '기분 나쁘다 정도로만 표현할 때', '화, 서운함, 불안, 실망, 무시당한 느낌 중 무엇에 가장 가까운가요?', 'Medium', '선택지를 주되 단정하지 않음', 'AI가 사용자의 감정을 확정하지 않음', null, 'Medium', true),
  ('ROM003-A', 'SSOL-ROM-003', 1, '사랑은 설렘 하나로 설명되지 않음', '사랑은 순간적인 감정뿐 아니라 애착, 돌봄, 선택, 행동, 관계 경험 등을 함께 포함하는 복합적인 경험으로 볼 수 있다.', array['Romance']::text[], array['사랑','설렘','권태']::text[], array['관계·소속']::text[], null, '설렘이 줄어 사랑이 끝났는지 묻는 경우', '지금 줄어든 건 설렘인가요, 애정인가요, 관계를 이어가고 싶은 마음인가요?', 'Medium', '다차원 관계 프레임', '사랑의 본질을 하나로 단정 금지', null, 'High', true),
  ('ROM003-B', 'SSOL-ROM-003', 2, '관계 고통에는 해석도 작용', '연애에서 느끼는 고통에는 상대의 행동뿐 아니라 자신의 기대, 두려움, 자기 가치, 과거 경험이 함께 영향을 줄 수 있다.', array['Romance','Self']::text[], array['관계고통','기대','자기가치']::text[], array['관계·소속','자기가치·인정']::text[], null, '상대 행동 때문에 매우 힘들 때', '상대의 행동 자체와, 그 행동이 나에게 어떤 의미로 받아들여져 더 아픈 부분을 나눠볼까요?', 'Medium', '상호작용적 탐색', '피해자 책임 암시 금지', array['폭력','강요','위협']::text[], 'High', true),
  ('ROM003-C', 'SSOL-ROM-003', 3, '한 사람의 노력만으로 관계를 통제할 수 없음', '관계는 노력으로 변화될 수 있는 부분이 있지만, 한 사람의 노력만으로 관계 전체를 통제할 수는 없다.', array['Romance']::text[], array['관계노력','통제','이별']::text[], array['관계·소속','통제·미래']::text[], null, '내가 더 노력하면 다 해결될지 묻는 경우', '이 관계에서 당신이 바꿀 수 있는 부분과 상대의 선택에 달린 부분은 각각 무엇인가요?', 'High', '자율성과 경계 원칙', '무한 노력 권고 금지', null, 'High', true),
  ('ROM003-D', 'SSOL-ROM-003', 4, '모든 감정의 즉시 공개가 최선은 아님', '사랑한다고 해서 모든 생각과 감정을 반드시 즉시 표현해야 하는 것은 아니며, 무엇을 언제 어떻게 공유할지는 관계의 목적과 영향을 함께 고려할 수 있다.', array['Romance','Relationship']::text[], array['정직','감정표현','비밀']::text[], array['관계·소속','직면']::text[], null, '모든 말을 해야 하는지 고민할 때', '이 말을 전하려는 목적은 이해받기, 문제해결, 감정배출 중 어디에 가까운가요?', 'Medium', '상황판단 프레임', '기만이나 위험 은폐를 정당화하지 않음', null, 'Medium', true),
  ('ROM003-E', 'SSOL-ROM-003', 5, '이별의 고통을 축소하지 않기', '이별과 상실은 강한 정서적·신체적 고통처럼 경험될 수 있으며 이를 단순히 마음먹기 나름이라고 축소하지 않는 것이 중요하다.', array['Romance','Self']::text[], array['이별','상실','고통']::text[], array['관계·소속','자기가치·인정']::text[], null, '이별 후 매우 힘들다고 할 때', '이별 후 가장 크게 무너진 부분은 감정, 수면·식사 같은 일상, 미래 기대 중 어디인가요?', 'High', '고통 인정', '검증 전 화상/골절 비교 수치 사용 금지', array['심한 기능저하','자살사고']::text[], 'High', true),
  ('ROM003-F', 'SSOL-ROM-003', 6, '애착유형은 궁합표가 아님', '불안형·회피형 같은 애착 개념은 관계 패턴을 이해하는 참고 틀일 수 있지만 두 사람의 궁합이나 성공 여부를 결정하는 운명표는 아니다.', array['Romance']::text[], array['애착','불안형','회피형','궁합']::text[], array['관계·소속']::text[], null, '애착유형 궁합 질문', '애착유형 이름을 빼고 실제 반복 행동만 본다면 어떤 장면이 자주 반복되나요?', 'High', '비고정적 스펙트럼 관점', '애착유형으로 사람/관계 판정 금지', null, 'High', true)
